L.push({ no: 51, title: 'Settlement Size-Functional Relationship', subtopic: US,
  notions: 'Threshold, range of goods, hierarchy.',
  focus: 'The relationship and examples; reasons.',
  competence: 'Learners are able to explain the relationship between settlement size and functions.',
  objectives: ['State the relationship between size and functions.', 'Give examples.', 'Explain the reasons for the relationship.'],
  recall: ['Villages have few services.', 'Big cities have universities.', 'Threshold is the minimum number of customers.'],
  situation: 'A village has a kiosk and a primary school, Garoua has banks and a regional hospital, and Yaoundé has universities, embassies and ministries.',
  sitQA: [['What is the problem in the situation?', 'Larger settlements have more functions.'], ['What does the village have?', 'A kiosk and a primary school.'], ['What does Yaoundé have?', 'Universities, embassies and ministries.']],
  justification: 'This lesson helps us to understand the hierarchy of settlements.',
  action: 'Plan services according to the size of settlements.',
  activities: [
    { sec: '1. THE RELATIONSHIP', img: 'size_function_big.png', caption: 'Size and functions.', q: 'What is the relationship between size and functions?', a: 'The larger the settlement, the more functions it has.', noProj: 'describe the graph.' },
    { sec: '2. EXAMPLES', img: 'hierarchy_big.png', caption: 'Settlement hierarchy.', q: 'Give examples at three levels.', a: 'Village (kiosk, primary school), town (bank, hospital), city (university, ministries).', noProj: 'give examples.' },
    { sec: '3. REASONS: THRESHOLD', img: 'range_threshold_big.png', caption: 'Range and threshold.', q: 'How does threshold explain the relationship?', a: 'High-order services need many customers, found only in large settlements.', noProj: 'discuss.' },
    { sec: '3. REASONS: RANGE', img: 'range_threshold_big.png', caption: 'Range.', q: 'How does range explain the relationship?', a: 'People travel far for rare goods, so these are found in big central towns.', noProj: 'discuss.' },
    { sec: '3. EXCEPTIONS', img: 'size_function_big.png', caption: 'Exceptions.', q: 'Give one exception to the relationship.', a: 'Mining or resort towns may be large but have few functions.', noProj: 'discuss.' },
  ],
  summary: [
    { title: '1. The Relationship and Examples', intro: 'Size and functions are related as follows:',
      items: [['Relationship:', 'The larger a settlement, the more and higher-order functions it has.'],
        ['Village:', 'It has low-order services such as a kiosk and a primary school.'],
        ['Town:', 'It has banks, secondary schools and a hospital.'],
        ['City:', 'It has universities, ministries and embassies.']],
      draw: { img: 'size_function_big.png', caption: 'size and functions' } },
    { title: '2. Reasons', intro: 'The relationship is explained by the following reasons:',
      items: [['Threshold:', 'High-order services need a large number of customers.'],
        ['Range:', 'People travel long distances for rare goods, so these locate in big towns.'],
        ['Exceptions:', 'Mining, resort and administrative towns may break the rule.']] },
  ],
  evaluation: [['State the size-function relationship.', 'The larger the settlement, the more functions it has.'], ['Explain it with threshold.', 'High-order services need many customers.']],
  remediation: ['The minimum number of customers for a service is the ______.', 'The distance people travel for a service is the ______.', 'A university is a ______-order service.'],
  remediationAnswers: '1. threshold 2. range 3. high',
  homework: 'Compare the services of your village or quarter with those of your regional capital.',
  hwAnswer: 'Village: kiosk, primary school, small market; regional capital: banks, hospital, secondary schools, big markets and administrative offices.',
  bilingual: [['Size', 'La taille'], ['Function', 'La fonction'], ['Hierarchy', 'La hiérarchie'], ['Low-order', "D'ordre inférieur"], ['High-order', "D'ordre supérieur"], ['Relationship', 'La relation']],
});

